/**
 * Bundles the public form's browser script (src/public/client/form.ts) with esbuild and writes it
 * as a string constant to src/public/client.generated.ts, which the renderer inlines. A test
 * fails when the generated file is out of date: run `pnpm --filter @freelyforms/api build:client`.
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const entry = join(import.meta.dirname, "../src/public/client/form.ts");
export const GENERATED_PATH = join(import.meta.dirname, "../src/public/client.generated.ts");

export async function generatedSource(): Promise<string> {
  const result = await build({
    entryPoints: [entry],
    bundle: true,
    minify: true,
    format: "iife",
    target: "es2020",
    legalComments: "none",
    write: false,
  });
  const code = result.outputFiles[0]?.text.trim() ?? "";
  // The script is inlined in a <script> element.
  if (/<\/script|<!--/i.test(code)) throw new Error("bundle contains </script or <!--");
  return [
    "// Generated by scripts/build-form-client.ts from src/public/client/form.ts. Do not edit.",
    `export const FORM_CLIENT_JS = ${JSON.stringify(code)};`,
    "",
  ].join("\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(GENERATED_PATH, await generatedSource());
}
